// requireBench skips the test unless it may talk to the real bench: the
// variable DEVDESK_NEXUS_BENCH is 1 and CI is empty. The same motif as
// internal/nettrace/live_linux_test.go.
func requireBench(t *testing.T) {
	t.Helper()
	if os.Getenv(benchGateEnv) != "1" {
		t.Skipf("set %s=1 to run against the real bench (it reaches the cluster)", benchGateEnv)
	}
	if os.Getenv("CI") != "" {
		t.Skip("the bench tests never run in CI")
	}
}

// liveBench is the running bench as the versioned descriptor and the secrets
// file describe it.
type liveBench struct {
	desc    Descriptor
	restURL string
	unknownUID = "00000000-0000-0000-0000-000000000000"
)

// requireScenarios skips the test unless the bench may be changed: the guard of
// requireBench, then DEVDESK_NEXUS_BENCH_SCENARIOS=1.
func requireScenarios(t *testing.T) {
	t.Helper()
	requireBench(t)
	if os.Getenv(benchScenariosEnv) != "1" {
		t.Skipf("set %s=1 as well (with %s=1) to run the scenarios: they cut the upstream and reset the bench", benchScenariosEnv, benchGateEnv)
	}
}

// scenarioBench is the running bench as the scenarios drive it: the library
// functions get the same doors (kubectl, skopeo, port-forward, secrets) the
// command gives them.
type scenarioBench struct {
	p       Params
	runner  Runner
	deps    SeedDeps
	restURL string
	admin   *client
	pull    Credentials
	secrets Secrets
}

// openScenarioBench builds the doors of a scenario from the environment of the
// bench (NEXUS_BENCH_*) and the stored secrets. It writes nothing.
func openScenarioBench(t *testing.T) scenarioBench {
	t.Helper()
	requireBench(t)
	requireScenarios(t)
	if deadline, ok := t.Deadline(); ok && time.Until(deadline) < scenarioMinTimeout {
		t.Fatalf("go test stops this run in %s; a scenario needs at least %s: rerun with -timeout 60m", time.Until(deadline).Round(time.Second), scenarioMinTimeout)
	}
	p, err := FromEnv(Defaults(), os.Getenv)
	if err != nil {
		t.Fatalf("parameters: %v", err)
	}
	if err := p.Validate(); err != nil {
		t.Fatalf("parameters: %v", err)
	}
	if !p.UpstreamIsBench() {
		t.Fatalf("the scenarios cut and reset the upstream of the bench: unset %s", envUpstreamURL)
	}
	secretsPath := p.SecretsPath
	if secretsPath == "" {
		secretsPath = secretsPathFor(t, p.Context, p.Namespace)
	}
	store, err := NewFileStore(secretsPath)
	if err != nil {
		t.Fatalf("NewFileStore: %v", err)
	}
	secrets, found, err := store.Load()
	if err != nil {
		t.Fatalf("read the secrets: %v", err)
	}
	if !found || secrets.AdminPassword == "" || secrets.PullPassword == "" {
		t.Fatal("the secrets file holds no admin or no bench-pull password: bring the bench up with `mise run nexus-bench:up`")
	}
	runner, err := NewExecRunner(p.Context)
	if err != nil {
		t.Fatalf("NewExecRunner: %v", err)
	}
	forwarder, err := NewExecPortForwarder(p.Context)
	if err != nil {
// CutUpstream scales the bench upstream to zero replicas and returns once no
// pod of it is left, a terminating one included: its volume is still mounted
// until it is gone. It reads first and writes only when the upstream is not
// already cut: one scale to zero, never retried. An upstream that is cut is
// still waited for, as a pod of an earlier cut may be terminating. Like
// EnsureUpstream, it refuses a custom upstream before any call, treats a
// missing Deployment as an error, runs no preflight, returns a cancelled
// context as is and accepts a nil out. The wait lasts until Params.Timeout.
func CutUpstream(ctx context.Context, r Runner, clk Clock, p Params, out io.Writer) error {
	if out == nil {
		out = io.Discard
	}
	if !p.UpstreamIsBench() {
		return customUpstreamError(p)
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	d := &deployer{pf: preflight{r: r, p: p}, w: upstreamWorkload(), tag: "upstream", clk: clk, out: out}
	state, err := d.readUpstream(ctx)
	if err != nil {
		return err
	}
	switch state {
	case UpstreamMissing:
		return missingUpstreamError(d)
	case UpstreamCut:
		d.say("the upstream is already cut")
	default:
		d.say("scaling the upstream to zero replicas")
		if err := d.scaleUpstream(ctx, 0); err != nil {
			return err
		}
	}
	return d.waitUpstreamGone(ctx)
}

// customUpstreamError refuses an upstream the bench does not deploy.
func customUpstreamError(p Params) *BenchError {
	return &BenchError{
		Kind: Unclassified,
		Cause: fmt.Sprintf("%s points at an upstream the bench did not deploy in namespace %q, and the bench scales only its own upstream",
			envUpstreamURL, p.Namespace),
		Check: "unset " + envUpstreamURL + " to use the bench upstream, or start and stop your own upstream registry yourself",
	}
}
